const dictionaries = { vi, en } as const;

export function useSandboxI18n() {
  const { lang } = useLanguage();
  const s = useCallback((key: SandboxKey, values?: Record<string, string | number>) => {
    const value = dictionaries[lang][key];
    if (!values) return value;
    return value.replace(/\{(\w+)\}/g, (token, name: string) => values[name] === undefined ? token : String(values[name]));
  }, [lang]);
  return { lang, locale: lang === "vi" ? "vi-VN" : "en-US", s };
}
